quests[13757] = { id = 13757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This is a fine blade and I have no doubt that it will serve me well in the tournament. You have my thanks, {name}.", objectives = "Retrieve the Ashwood Brand and bring it to Jaelyne Evensong at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13758] = { id = 13758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Of all the times to have such rotten luck! My blade is missing!\n\nI've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "<Jaelyne accepts the Blade of Drak'Mar from you.>\n\nA fine weapon, and perfectly balanced. It will serve me well in the next match.", objectives = "Bring the Blade of Drak'Mar to Jaelyne Evensong at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13759] = { id = 13759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "That's the last time I ever spar with a death knight.\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", progress = "Did you win the blade I seek?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, {name}.", objectives = "Jaelyne Evensong at the Argent Tournament Grounds wants you to bring her Winter's Edge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13760] = { id = 13760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", completion = "Welcome back from your exercises, {name}. Even while we practice for the competition, it's good to remind ourselves that the Scourge is still out there.", objectives = "Illestria Bladesinger at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13761] = { id = 13761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. The people of Darnassus are looking forward to seeing us win the melee. To that end, they've been honing their skills against the valiants representing the other Alliance capitals.\n\nI suggest you do the same.\n\nThe Alliance Valiants' Ring is just outside our tent. Go to the stables on the outside the pavilion, equip your lance, mount the stabled Darnassian mistsaber, and challenge the valiants.", progress = "Have you completed your training for the grand melee?", completion = "Well done. Training against the other valiants is one of the best ways to prepare yourself for tournament competition. I know you'll make Darnassus proud, {name}.", objectives = "Bring 3 Marks of the Valiant to Airae Starseeker at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13762] = { id = 13762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "I've heard that the Alliance champions are seeking after ancient blades for their warriors. We can't afford to let them have that kind of advantage.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This blade should be enough to best anything those Alliance entrants can come up with.", objectives = "Retrieve the Ashwood Brand and bring it to Mokra the Skullcrusher at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13763] = { id = 13763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "This is a fine weapon that will help me crush the competition. Thank you, {name}.", objectives = "Bring the Blade of Drak'Mar to Mokra the Skullcrusher at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13764] = { id = 13764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "Curse that death knight for breaking my sword!\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", progress = "Did you win the blade?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, {name}.", objectives = "Mokra the Skullcrusher at the Argent Tournament Grounds wants you to bring him Winter's Edge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13765] = { id = 13765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", completion = "A good day of training will never hurt anyone. It's good to see you keeping up.", objectives = "Akinos at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13766] = { id = 13766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Closure is Only Natural", description = "Through the ground I can feel more demons being brought into our world. Soon there will be too many and we will be overrun without hope of turning them back.\n\nTake this piece of me and return to Demon Fall Canyon and Demon Fall Ridge, south of Felfire Hill. Aim the bough at a demon gate and concentrate. I have stored a portion of the forest's life force in its wood, and it will close the gate.", completion = "With their gates closed and no further reinforcements coming, it is only a matter of time now before the demons are no more.\n\nYou are a hero of the forest, {name}. I give you thanks on behalf of all of Ashenvale's creatures!", objectives = "Use Gnarl's Bough to close 10 Demon Gates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13767] = { id = 13767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.\n\nIt will help prepare you for the rigors of tournament combat.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Orgrimmar wolf, and challenge the valiants. They wait in the Horde Valiants' Ring just outside our tent.", progress = "Have you completed your training for the grand melee?", completion = "Training against the other valiants will sharpen your claws and hone your battle instincts. When the competition begins, you will be ready.", objectives = "Bring 3 Marks of the Valiant to Morah Worgsister at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13768] = { id = 13768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "I've heard that the Alliance champions are seeking after ancient blades for their warriors. We can't afford to let them have that kind of advantage.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This blade should be enough to best anything those Alliance entrants can come up with.", objectives = "Retrieve the Ashwood Brand and bring it to Zul'tore at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
