quests[13772] = { id = 13772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.\n\nIt will help prepare you for the rigors of tournament combat.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Darkspear raptor, and challenge the valiants. They wait in the Horde Valiants' Ring just outside our tent.", progress = "Have you completed your training for the grand melee?", completion = "Training against other valiants will quickly teach you what you need to know to best them. Keep it up and you'll have no trouble defeating them in competition.", objectives = "Bring 3 Marks of the Valiant to Gahju at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
